    internal static class PatchBridge { internal static RuntimeSaveAuthorization SaveAuthorization;internal static RefusalPolicyFacade Persistence; }
    internal static class NativePersistenceIsolation { internal static RuntimeSaveTarget Project(Kingmaker.EntitySystem.Persistence.SaveInfo value)=>value.Target; }
    internal sealed class RefusalPolicyFacade
    {
        internal bool Accepted;internal int Calls,Rejected,Disposals;
        internal bool CanLoadBeforeWorldReplacement(Kingmaker.EntitySystem.Persistence.SaveInfo value){Calls++;if(!Accepted)Rejected++;return Accepted;}
        internal bool PrepareForNativeWorldDisposal(){Disposals++;return true;}
    }
    internal static class LoadRefusalPatchAdapter
    {
__ACTUAL_PREFIXES__
        internal static bool Invoke(string entry,Kingmaker.EntitySystem.Persistence.SaveInfo save)
        {if(entry=="Game.LoadGameFromMainMenu")return GameMainMenuLoadAdmissionPrefix(save);if(entry=="Game.LoadGame")return GameLoadAdmissionPrefix(save);return GameSmokeLoadAdmissionPrefix(save);}
    }
}

